style.css:
@-moz-document domain("chatgpt.com") {
body::before,
    body::after {
        content: "";
        position: fixed;
        top: -10%;
        left: 0;
        width: 100%;
        height: 120%;
        pointer-events: none;
        z-index: 9999;
        background-repeat: repeat;
        animation-timing-function: linear;
        animation-iteration-count: infinite;
    }

    /* Pink leaves */
    body::before {
        background-image:
            radial-gradient(circle, rgba(255,182,193,0.9) 0 6px, transparent 7px),
            radial-gradient(circle, rgba(255,105,180,0.7) 0 4px, transparent 5px),
            radial-gradient(circle, rgba(255,192,203,0.8) 0 5px, transparent 6px);

        background-size:
            120px 120px,
            180px 180px,
            240px 240px;

        animation: floatLeaves 18s linear infinite;
        opacity: 0.7;
    }

    /* Green leaves */
    body::after {
        background-image:
            radial-gradient(circle, rgba(144,238,144,0.7) 0 5px, transparent 6px),
            radial-gradient(circle, rgba(152,251,152,0.6) 0 4px, transparent 5px),
            radial-gradient(circle, rgba(60,179,113,0.7) 0 6px, transparent 7px);

        background-size:
            160px 160px,
            220px 220px,
            280px 280px;

        animation: floatLeavesReverse 24s linear infinite;
        opacity: 0.5;
    }

    @keyframes floatLeaves {
        0% {
            transform: translateY(-10%) translateX(0) rotate(0deg);
        }

        50% {
            transform: translateY(50%) translateX(20px) rotate(180deg);
        }

        100% {
            transform: translateY(110%) translateX(-20px) rotate(360deg);
        }
    }

    @keyframes floatLeavesReverse {
        0% {
            transform: translateY(110%) translateX(0) rotate(0deg);
        }

        50% {
            transform: translateY(50%) translateX(-30px) rotate(-180deg);
        }

        100% {
            transform: translateY(-10%) translateX(30px) rotate(-360deg);
        }
    }
}
